commands.command:
set -eu
install -d -m 700 /etc/nginx/tls
install -m 644 /tmp/ca.crt /usr/local/share/ca-certificates/fleet-internal-ca.crt
install -m 644 /tmp/node2.crt /etc/nginx/tls/node2.crt
install -m 600 /tmp/node2.key /etc/nginx/tls/node2.key
rm -f /tmp/ca.crt /tmp/node2.crt /tmp/node2.key
update-ca-certificates
cat > /etc/nginx/nginx.conf <<'FLEET_NGINX'
user nginx;
worker_processes auto;
error_log /var/log/nginx/error.log warn;
pid /run/nginx/nginx.pid;

events {
    worker_connections 1024;
}

http {
    include /etc/nginx/mime.types;
    default_type text/plain;
    server {
        listen 8443 ssl;
        listen [::]:8443 ssl;
        server_name node2;
        ssl_certificate /etc/nginx/tls/node2.crt;
        ssl_certificate_key /etc/nginx/tls/node2.key;
        ssl_protocols TLSv1.2 TLSv1.3;
        location / {
            return 200 "node2 Fleet Internal CA HTTPS\n";
        }
    }
}
FLEET_NGINX
nginx -t
rc-update add nginx default
rc-service nginx restart
openssl verify -CApath /etc/ssl/certs /etc/nginx/tls/node2.crt
rc-service nginx status
